# Cas test_capacites du heros MANTIS (Mantis, BlueHG, prefixe `mt`) : noms commencant par le card_id
# (substituer_pack.py filtre dessus : `tools/substituer_pack.py <game_dir> <port> mt0`).
#
# Rappels de montage :
#  - le deck `mantis` demarre en ALTER EGO (mt001b) ; `Puzzle.ChangeToFace('mt001b', 'mt001a')` le passe en HEROS ;
#  - Rhino 01094 est le vilain (14 PV), 01097b son complot principal ; 01101 Hydra Mercenary (3 PV, Garde 1), 01172 Whiplash (4 PV, Riposte 1), 01102 Sandman (4 PV, Tenace) ;
#  - ressources : 01088 Energy = YY, 01089 Genius = BB, 01090 Strength = RR ;
#  - `Puzzle.Confuse` / `Puzzle.Stun` BASCULENT le statut (le 2e appel le retire) ;
#  - SANS_BOOST : un deck rencontre sans icone de boost pour les attaques d'ennemi.
HEROS = "Puzzle.ChangeToFace('mt001b', 'mt001a')"
SANS_BOOST = ["Puzzle.EmptyEncounterDeck()",
              "Puzzle.CreateEncounterDeck('01105', '01105', '01105', '01105', '01105', '01105', '01105', '01105')"]


def M(carte):
    return f"Puzzle.PutIntoPlay('{carte}', under_control=True)"


def _c(nom, pourquoi, mise, declencher, attendu, **cle):
    cas = {'nom': nom, 'pourquoi': pourquoi, 'scenario': cle.pop('scenario', 'rhino'), 'heros': cle.pop('heros', 'mantis'),
           'mise_en_place': list(mise), 'declencher': list(declencher), 'verifier': cle.pop('verifier', 'etat_attendu'), 'attendu': attendu}
    cas.update(cle)
    return cas


